import React, { useState, useEffect } from 'react';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import { PlusCircle, LayoutDashboard, Calendar as CalendarIcon, Database, ShieldCheck, Printer, AlertTriangle } from 'lucide-react';

function App() {
  const [departments, setDepartments] = useState([
    { id: 1, name: "College of Computer Studies", code: "CCS" },
    { id: 2, name: "Business Administration", code: "CBA" }
  ]);

  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  const addDepartment = () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Department Code (e.g., PSYCH):");
    if (name && code) {
      setDepartments([...departments, { id: Date.now(), name, code: code.toUpperCase() }]);
    }
  };

  // --- THE GLOBAL CONFLICT SCRUBBER ---
  const handleScheduleGenerated = (newAssignments, newDates, deptCode) => {

    // 1. Prepare the new assignments with metadata
    const taggedNewData = newAssignments.map(session => {
      // Check for conflicts against EVERY OTHER department already in globalSchedule
      const conflict = globalSchedule.find(existing => 
        existing.dept_code !== deptCode && // Don't conflict with yourself
        existing.exam_date === session.exam_date &&
        (existing.room === session.room || existing.proctor === session.proctor) &&
        // Time Overlap Logic: (StartA < EndB) AND (EndA > StartB)
        (session.start_time < existing.end_time && session.end_time > existing.start_time)
      );

      return {
        ...session,
        dept_code: deptCode,
        hasConflict: !!conflict,
        conflictDetail: conflict ? `Conflict with ${conflict.dept_code} in ${conflict.room}` : null
      };
    });

    // 2. Update Global Pool (Replace old dept data with fresh generated data)
    setGlobalSchedule(prev => {
      const otherDepts = prev.filter(item => item.dept_code !== deptCode);
      return [...otherDepts, ...taggedNewData];
    });

    // 3. Update Calendar Dates
    setAllExamDates(prev => {
      const combined = [...new Set([...prev, ...newDates])];
      return combined.filter(d => d).sort((a, b) => new Date(a) - new Date(b));
    });
  };

  // --- CALCULATE SYSTEM HEALTH ---
  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">

      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-500/20">
            <LayoutDashboard size={24} className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter leading-none">EXAM_FLOW <span className="text-blue-500 text-xs font-bold ml-1 uppercase">PRO v2.0</span></h1>
            <p className="text-[9px] text-slate-400 font-black tracking-[0.3em] uppercase mt-1">Unified Conflict Resolver</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
            <div className={`hidden md:flex items-center gap-2 px-4 py-2 rounded-xl border transition-all ${conflictCount > 0 ? 'bg-rose-900/20 border-rose-500/50' : 'bg-slate-800 border-slate-700'}`}>
                {conflictCount > 0 ? (
                  <>
                    <AlertTriangle size={16} className="text-rose-500 animate-pulse"/>
                    <span className="text-[10px] font-black text-rose-300 uppercase">{conflictCount} Conflicts Detected</span>
                  </>
                ) : (
                  <>
                    <ShieldCheck size={16} className="text-emerald-500"/>
                    <span className="text-[10px] font-black text-slate-300 uppercase">System Optimal</span>
                  </>
                )}
            </div>
            <button onClick={addDepartment} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest flex items-center gap-2 shadow-xl shadow-blue-600/20 transition-all active:scale-95">
              <PlusCircle size={18} /> Add Dept
            </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">

        {/* STATS BAR */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
            <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Exam Blocks</p>
                <p className="text-4xl font-black text-slate-900">{globalSchedule.length}</p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Managed Depts</p>
                <p className="text-4xl font-black text-slate-900">{departments.length}</p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-200">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Resource Status</p>
                <p className={`text-3xl font-black uppercase ${conflictCount > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                  {conflictCount > 0 ? 'Action Required' : 'Optimal'}
                </p>
            </div>
        </div>

        {/* INPUT: DEPARTMENT CARDS */}
        <div className="space-y-12 mb-20">
          <div className="flex items-center gap-3">
            <Database className="text-slate-400" size={20}/>
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em]">Resource Management Layer</h3>
          </div>
          {departments.map((dept) => (
            <DepartmentCard 
              key={dept.id} 
              deptId={dept.id}
              deptName={dept.name} 
              deptCode={dept.code}
              // PASS THE GLOBAL SCHEDULE DOWN so the card can check for Proctor Reactivation
              globalSchedule={globalSchedule}
              onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
            />
          ))}
        </div>

        {/* OUTPUT: TIMELINE */}
        <div className="pt-16 border-t border-slate-200">
            {globalSchedule.length > 0 ? (
            <div className="animate-in fade-in slide-in-from-bottom-10 duration-1000">
                <div className="flex flex-col md:flex-row justify-between items-end mb-10 gap-6">
                <div>
                    <div className="flex items-center gap-2 mb-4">
