                <button onClick={() => window.print()} className="bg-white border-2 border-slate-900 px-10 py-5 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl hover:bg-slate-900 hover:text-white transition-all flex items-center gap-3">
